 [("gyrus-precentral", "gyrus-precentral-l", "ipsilateral"), ("internal-capsule", "internal-capsule-l", "ipsilateral"), ("pyramid", "brainstem", "ipsilateral", "passes the decussation uncrossed"), ("spinal-white-columns", "spinal-cord", "ipsilateral", "anterior funiculus beside the anterior median fissure, cervical and upper thoracic segments mainly"), ("spinal-grey-anterior-horn", "spinal-cord", "bilateral", "medial motor column via the anterior white commissure")],
