 ("Anterior white commissure over several segments", "spinal-white-columns", "Crosses less abruptly than the pain fibers."),
 [("dorsal-root-ganglion", None, "ipsilateral"), ("spinal-grey-posterior-horn", "spinal-cord", "ipsilateral"), ("spinal-white-columns", "spinal-cord", "contralateral", "anterior funiculus"), ("medial-lemniscus", "tract-medial-lemniscus-l", "contralateral", "joins the spinal lemniscus and runs beside the medial lemniscus in the brainstem"), ("thalamus-vpl", "thalamus-ventral-posterior-ventrolateral-l", "contralateral"), ("gyrus-postcentral", "gyrus-postcentral-l", "contralateral")],
 "Ventral posterolateral nucleus of the thalamus and the somatosensory cortex.",
 [("Hemicord lesion", "Crude touch largely preserved on both sides because of the dual pathway", "n/a"), ("Anterior cord infarct", "Loss of pain, temperature and crude touch below the level with preserved posterior column function", "bilateral")],
 ["Test pain and vibration, not light touch, when localizing a cord lesion: touch has two routes and stays", "The anterior spinothalamic tract is the reason 'sensory loss' after a cord lesion is rarely total"],
